const fs=require('fs'),path=require('path');const root=path.resolve(__dirname,'..');
const specs=[['02_specificatie/01_VIZIUNE_SI_SPECIFICATIE.md','manager','REQ-'],['01_cercetare/piata_feedback_ux.md','research_ux','U'],['03_arhitectura/01_arhitectura_apple.md','apple_architecture','AP-R'],['04_cad_printare/capitol_cad_metrologie_printare.md','cad_printing','CAD-']];
const reqs=[];for(const [file,owner,prefix] of specs){const lines=fs.readFileSync(path.join(root,file),'utf8').split(/\r?\n/);lines.forEach((l,i)=>{const m=l.match(/^\|\s*((?:REQ-|CAD-)\d{3}|AP-R\d{2}|U\d{2})\s*\|/);if(!m)return;const cells=l.split('|').slice(1,-1).map(x=>x.trim());let requirement,criterion,priority='see_canonical_scope';if(prefix==='U'){priority=cells[1];requirement=cells[2];criterion=cells[3];}else{requirement=cells[1];criterion=cells.slice(2).join(' / ');}reqs.push({id:m[1],owner,source_file:file,line:i+1,priority,requirement,criterion,canonical:'05_validare/CRITERII_CANONICE.md',verification_plan:prefix==='REQ-'?cells.at(-1):prefix==='AP-R'?'03_arhitectura/01_arhitectura_apple.md secțiunea experimente':prefix==='CAD-'?'04_cad_printare/capitol_cad_metrologie_printare.md protocol':'01_cercetare/piata_feedback_ux.md plan UX',implementation:'not_started',test_status:'not_run',evidence:null});});}
if(new Set(reqs.map(x=>x.id)).size!==reqs.length)throw Error('Duplicate requirements');
fs.writeFileSync(path.join(root,'05_validare/TRASABILITATE.json'),JSON.stringify({generated_at:new Date().toISOString(),note:'Cerințe propuse; fiecare rezultat de implementare și test este neexecutat',requirements:reqs},null,2)+'\n');
const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';const columns=['id','owner','source_file','line','priority','requirement','criterion','verification_plan','implementation','test_status','evidence'];fs.writeFileSync(path.join(root,'05_validare/TRASABILITATE.csv'),columns.join(',')+'\n'+reqs.map(r=>columns.map(c=>quote(r[c])).join(',')).join('\n')+'\n');console.log('Requirements: '+reqs.length);
